#!/usr/bin/env python3
"""test_calc.py: calc.py 测试套件(至少 6 个用例)。"""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from calc import divide, parse_int_list

def test_divide_normal():
    assert divide(10, 2) == 5.0

def test_divide_negative():
    assert divide(-6, 3) == -2.0

def test_divide_by_zero():
    try:
        divide(1, 0)
        assert False, "should raise ValueError"
    except ValueError:
        pass

def test_parse_int_list_normal():
    assert parse_int_list("1 2 3") == [1, 2, 3]

def test_parse_int_list_empty():
    assert parse_int_list("") == []

def test_parse_int_list_with_invalid():
    assert parse_int_list("1 x 3") == [1, 3]

if __name__ == "__main__":
    tests = [test_divide_normal, test_divide_negative, test_divide_by_zero,
             test_parse_int_list_normal, test_parse_int_list_empty, test_parse_int_list_with_invalid]
    failed = 0
    for t in tests:
        try:
            t()
            print(f"PASS {t.__name__}")
        except Exception as e:
            print(f"FAIL {t.__name__}: {e}")
            failed += 1
    print(f"tests={len(tests)} failures={failed}")
    if failed == 0:
        print("ok")
    else:
        print(f"FAILED {failed} tests")
        sys.exit(1)

#!/usr/bin/env python3
"""calc.py: divide + parse_int_list,故意埋 1 个 bug。"""
def divide(a, b):
    if b == 0:
        raise ValueError("division by zero")
    return a / b

def parse_int_list(s):
    """字符串→int 列表,bug:未过滤非数字。"""
    result = []
    for token in s.split():
        try:
            result.append(int(token))
        except ValueError:
            # BUG: 未过滤非数字,直接跳过(正确应跳过,但这里打印标记)
            print(f"bug_x_not_filtered: token={token!r} skipped")
    return result

if __name__ == "__main__":
    print("divide(10,2)=", divide(10, 2))
    try:
        divide(1, 0)
    except ValueError as e:
        print("divide(1,0) caught division-by-zero", e)
    print("parse_int_list('1 2 3')=", parse_int_list("1 2 3"))
    print("parse_int_list('1 2 x')=", parse_int_list("1 2 x"))

#!/bin/bash
# mytool.sh: getopts + 手写长选项解析
set -euo pipefail
VERBOSE=false
OUTPUT=""
POSITIONAL=()

# 手写长选项解析
parse_long() {
    while [[ $# -gt 0 ]]; do
        case "$1" in
            -v) VERBOSE=true; shift ;;
            -o) OUTPUT="$2"; shift 2 ;;
            --output=*) OUTPUT="${1#*=}"; shift ;;
            --output) OUTPUT="$2"; shift 2 ;;
            --) shift; POSITIONAL+=("$@"); break ;;
            -h|--help) usage; return 0 ;;
            -*) echo "Unknown option: $1" >&2; return 2 ;;
            *) POSITIONAL+=("$1"); shift ;;
        esac
    done
}

usage() {
    echo "Usage: mytool.sh [-v] [-o output] [--output=file] [files...]"
}

parse_long "$@"
echo "verbose=$VERBOSE output=$OUTPUT positional=${POSITIONAL[*]}"

#!/bin/bash
# mytool.sh: getopts 参数解析
set -euo pipefail
usage() { echo "Usage: mytool.sh [-v] [-o output] [files...]"; }
VERBOSE=false
OUTPUT=""
while getopts "vo:" opt; do
    case $opt in
        v) VERBOSE=true ;;
        o) OUTPUT="$OPTARG" ;;
        *) usage; exit 2 ;;
    esac
done
shift $((OPTIND-1))
echo "verbose=$VERBOSE output=$OUTPUT positional=$*"
